import{_ as t,o as r,c as d,a4 as i}from"./chunks/framework.BUqnS5H7.js";const f=JSON.parse('{"title":"导论：什么是 AI Agent，这条路怎么走","description":"","frontmatter":{},"headers":[],"relativePath":"ai/01-导论.md","filePath":"ai/01-导论.md"}'),e={name:"ai/01-导论.md"};function s(n,a,l,c,o,g){return r(),d("div",null,[...a[0]||(a[0]=[i('<h1 id="导论-什么是-ai-agent-这条路怎么走" tabindex="-1" data-src-line="1" data-src-file="ai/01-导论.md">导论：什么是 AI Agent，这条路怎么走 <a class="header-anchor" href="#导论-什么是-ai-agent-这条路怎么走" aria-label="Permalink to &quot;导论：什么是 AI Agent，这条路怎么走&quot;">​</a></h1><p data-src-line="3" data-src-file="ai/01-导论.md">这是这套文档的第一篇。在动手写任何代码之前，先把一件事彻底讲清楚：<strong>你到底要学的是什么。</strong> 很多人学了几个月，才发现自己一直学错了对象——学的是「聊天」，不是「Agent」。这一篇就是那张「地图」，让你从一开始就站在正确的位置上。</p><p data-src-line="5" data-src-file="ai/01-导论.md">读完这一篇，你要能回答三个问题：<strong>Agent 到底是什么、为什么要费劲搞它、接下来 11 篇怎么走。</strong></p><hr><h2 id="_1-agent-是什么" tabindex="-1" data-src-line="9" data-src-file="ai/01-导论.md">1. Agent 是什么 <a class="header-anchor" href="#_1-agent-是什么" aria-label="Permalink to &quot;1. Agent 是什么&quot;">​</a></h2><h3 id="_1-1-一个反直觉的现象" tabindex="-1" data-src-line="11" data-src-file="ai/01-导论.md">1.1 一个反直觉的现象 <a class="header-anchor" href="#_1-1-一个反直觉的现象" aria-label="Permalink to &quot;1.1 一个反直觉的现象&quot;">​</a></h3><p data-src-line="13" data-src-file="ai/01-导论.md">打开各种 AI 产品，你会发现一个奇怪的现象：同样是背后的大模型，有的产品<strong>只会「陪你聊天」</strong>，有的却能<strong>帮你订机票、查数据、写代码、自动跑完一整个流程</strong>。</p><p data-src-line="15" data-src-file="ai/01-导论.md">差别不在模型本身——模型还是那个模型——<strong>差别在模型外面那层「壳」。</strong></p><h3 id="_1-2-一句话定义" tabindex="-1" data-src-line="17" data-src-file="ai/01-导论.md">1.2 一句话定义 <a class="header-anchor" href="#_1-2-一句话定义" aria-label="Permalink to &quot;1.2 一句话定义&quot;">​</a></h3><blockquote data-src-line="19" data-src-file="ai/01-导论.md"><p data-src-line="19" data-src-file="ai/01-导论.md"><strong>AI Agent = 大模型（LLM）＋ 工具（Tools）＋ 记忆（Memory）＋ 循环（Loop）</strong></p></blockquote><p data-src-line="21" data-src-file="ai/01-导论.md">这四个词，每一个都是「壳」的一部分。缺一个，它就从「能办事的 Agent」退化回「会说话的聊天机器人」。</p><h3 id="_1-3-一个贯穿全书的比喻" tabindex="-1" data-src-line="23" data-src-file="ai/01-导论.md">1.3 一个贯穿全书的比喻 <a class="header-anchor" href="#_1-3-一个贯穿全书的比喻" aria-label="Permalink to &quot;1.3 一个贯穿全书的比喻&quot;">​</a></h3><p data-src-line="25" data-src-file="ai/01-导论.md">把这个比喻记牢，后面 10 篇都在反复用到它：</p><blockquote data-src-line="27" data-src-file="ai/01-导论.md"><p data-src-line="27" data-src-file="ai/01-导论.md"><strong>大模型是一个聪明但手无寸铁的「实习生」</strong>——它啥都懂，但一个人干不了活。<strong>Agent 就是给这个实习生配上了「工牌、电脑、权限、记事本」</strong>，让它能<strong>自己规划、自己调用工具、自己记住进展、反复推进，直到把活干完</strong>。</p></blockquote><ul data-src-line="29" data-src-file="ai/01-导论.md"><li data-src-line="29" data-src-file="ai/01-导论.md"><strong>工牌 / 权限</strong> = 工具调用 + 权限控制（04、06、10 篇）</li><li data-src-line="30" data-src-file="ai/01-导论.md"><strong>电脑</strong> = 能执行外部操作的能力（04 篇）</li><li data-src-line="31" data-src-file="ai/01-导论.md"><strong>记事本</strong> = 记忆系统（08 篇）</li><li data-src-line="32" data-src-file="ai/01-导论.md"><strong>反复推进</strong> = 循环 / 编排（04、07 篇）</li></ul><p data-src-line="34" data-src-file="ai/01-导论.md"><strong>第一条要抓住的认知：Agent 不是「更强的聊天机器人」，而是「一套让模型能自主干活的系统」。</strong> 你学的不是模型，是那套系统。</p><hr><h2 id="_2-为什么需要-agent" tabindex="-1" data-src-line="38" data-src-file="ai/01-导论.md">2. 为什么需要 Agent <a class="header-anchor" href="#_2-为什么需要-agent" aria-label="Permalink to &quot;2. 为什么需要 Agent&quot;">​</a></h2><h3 id="_2-1-聊天机器人和-agent-到底差在哪" tabindex="-1" data-src-line="40" data-src-file="ai/01-导论.md">2.1 聊天机器人和 Agent，到底差在哪 <a class="header-anchor" href="#_2-1-聊天机器人和-agent-到底差在哪" aria-label="Permalink to &quot;2.1 聊天机器人和 Agent，到底差在哪&quot;">​</a></h3><p data-src-line="42" data-src-file="ai/01-导论.md">很多人以为 Agent 就是「聊天机器人 + 联网」。这是错的。两者的本质区别在**「谁在推动事情往前走」**：</p><ul data-src-line="44" data-src-file="ai/01-导论.md"><li data-src-line="44" data-src-file="ai/01-导论.md"><strong>聊天机器人</strong>：你问一句，它答一句。答完就结束，<strong>不会主动做任何事</strong>，所有主动权都在你手里。</li><li data-src-line="45" data-src-file="ai/01-导论.md"><strong>Agent</strong>：你给一个目标，它<strong>自己拆解、自己行动、自己检查、自己重试</strong>，直到目标达成或确认失败。主动权在它手里。</li></ul><p data-src-line="47" data-src-file="ai/01-导论.md">一句话概括这个区别：</p><blockquote data-src-line="49" data-src-file="ai/01-导论.md"><p data-src-line="49" data-src-file="ai/01-导论.md">聊天机器人回答「答案是什么」；Agent 完成「事该怎么做」。</p></blockquote><p data-src-line="51" data-src-file="ai/01-导论.md">举个具体场景感受一下：让聊天机器人「帮我订明天去上海的机票」，它只会回你一段「你可以去携程查一下」的文字。而一个真正的 Agent，会<strong>自己查你的日程 → 查航班 → 比价 → 选定 → （经你确认）下单</strong>，全程你不是在「问它」，是在「派活给它」。</p><h3 id="_2-2-为什么模型「不够用」-非要加壳" tabindex="-1" data-src-line="53" data-src-file="ai/01-导论.md">2.2 为什么模型「不够用」，非要加壳 <a class="header-anchor" href="#_2-2-为什么模型「不够用」-非要加壳" aria-label="Permalink to &quot;2.2 为什么模型「不够用」，非要加壳&quot;">​</a></h3><p data-src-line="55" data-src-file="ai/01-导论.md">既然模型已经这么聪明，为什么还要费劲搞「工具、记忆、循环」这套壳？因为模型有三个<strong>结构性短板</strong>，不加壳就治不好：</p><p data-src-line="57" data-src-file="ai/01-导论.md"><strong>短板一：模型是「无状态」的。</strong> 它不记得刚才说过什么，更不记得你上个月的偏好。每次调用都是孤立计算。想让它「记住」，只能靠外部记忆（08 篇专门讲）。</p><p data-src-line="59" data-src-file="ai/01-导论.md"><strong>短板二：模型「只能生成文字」。</strong> 它不会真的去查数据库、真的发邮件、真的改文件——它只会「生成一段看起来像查过的话」。想让它「办事」，就得给它工具去调用（04 篇）。</p><p data-src-line="61" data-src-file="ai/01-导论.md"><strong>短板三：模型会「一本正经地胡说八道」。</strong> 尤其在它不知道答案的时候，它会自信地编一个。想让它「靠谱」，就得有循环去校验（04 篇）、有护栏去约束（10 篇）。</p><p data-src-line="63" data-src-file="ai/01-导论.md"><strong>关键的取舍（先给你交代成本）</strong>：给模型加这层壳，换来「能自主干活」，代价是<strong>复杂度陡增</strong>——工具怎么定义、记忆怎么管、循环怎么不失控、成本怎么不烧穿，每一个都是真刀真枪的工程难题。<strong>而你手里的这 11 篇文档，讲的就是这些难题逐个怎么解。</strong></p><hr><h2 id="_3-11-步进阶地图" tabindex="-1" data-src-line="67" data-src-file="ai/01-导论.md">3. 11 步进阶地图 <a class="header-anchor" href="#_3-11-步进阶地图" aria-label="Permalink to &quot;3. 11 步进阶地图&quot;">​</a></h2><p data-src-line="69" data-src-file="ai/01-导论.md">下面是这条路的全景。每一篇解决一个核心问题，<strong>从「会对话」一路走到「从 0 到 1 上线一个能用的 Agent」</strong>。</p><p data-src-line="71" data-src-file="ai/01-导论.md">这条路的编排逻辑是「先概念/手搓 → 再框架 → 再案例/实战」，是主流 Agent 课程公认的最有效进阶路径：</p><table tabindex="0"><thead data-src-line="73" data-src-file="ai/01-导论.md"><tr data-src-line="73" data-src-file="ai/01-导论.md"><th>编号</th><th>主题</th><th>解决的核心问题</th></tr></thead><tbody data-src-line="75" data-src-file="ai/01-导论.md"><tr data-src-line="75" data-src-file="ai/01-导论.md"><td>01</td><td>导论</td><td>Agent 是什么，这条路怎么走（就是本文）</td></tr><tr data-src-line="76" data-src-file="ai/01-导论.md"><td>02</td><td>LLM 接口与提示词工程</td><td>怎么让模型<strong>按你的要求好好说话</strong></td></tr><tr data-src-line="77" data-src-file="ai/01-导论.md"><td>03</td><td>RAG 架构与工程落地</td><td>怎么让模型<strong>懂你的私有数据</strong></td></tr><tr data-src-line="78" data-src-file="ai/01-导论.md"><td>04</td><td>Function Calling 与 Agent 范式</td><td>怎么给模型<strong>装上手脚去办事</strong></td></tr><tr data-src-line="79" data-src-file="ai/01-导论.md"><td>05</td><td>框架化开发（Python 三件套）</td><td>怎么用框架<strong>把上面这些落成生产系统</strong></td></tr><tr data-src-line="80" data-src-file="ai/01-导论.md"><td>06</td><td>MCP 协议与工具生态</td><td>怎么让工具<strong>像 USB-C 一样即插即用</strong></td></tr><tr data-src-line="81" data-src-file="ai/01-导论.md"><td>07</td><td>Agent 编排与状态持久化</td><td>一个 Agent 干不了，怎么<strong>拆成一队分工</strong></td></tr><tr data-src-line="82" data-src-file="ai/01-导论.md"><td>08</td><td>Memory 长期记忆</td><td>怎么让 Agent <strong>忘不了、不记错、不记满</strong></td></tr><tr data-src-line="83" data-src-file="ai/01-导论.md"><td>09</td><td>评估与可观测性</td><td>怎么<strong>看清 Agent 在干什么、干得怎么样</strong></td></tr><tr data-src-line="84" data-src-file="ai/01-导论.md"><td>10</td><td>安全护栏</td><td>怎么给 Agent <strong>上保险，防它干蠢事和坏事</strong></td></tr><tr data-src-line="85" data-src-file="ai/01-导论.md"><td>11</td><td>端到端实战</td><td>把 01–10 <strong>串起来，真实搭一个生产 Agent</strong></td></tr></tbody></table><h3 id="_3-1-这条路的三个阶段" tabindex="-1" data-src-line="87" data-src-file="ai/01-导论.md">3.1 这条路的三个阶段 <a class="header-anchor" href="#_3-1-这条路的三个阶段" aria-label="Permalink to &quot;3.1 这条路的三个阶段&quot;">​</a></h3><p data-src-line="89" data-src-file="ai/01-导论.md">把 11 篇归个类，你会看得更清楚：</p><ol data-src-line="91" data-src-file="ai/01-导论.md"><li data-src-line="91" data-src-file="ai/01-导论.md"><strong>第 1 阶段（01–04）：手搓期</strong> —— 在没有任何框架的情况下，把 Agent 的每一个零件「裸」着搭一遍。<strong>这是故意不给你框架的</strong>，因为只有手搓过，你才知道框架替你省了什么、框架的抽象层在干什么。</li><li data-src-line="92" data-src-file="ai/01-导论.md"><strong>第 2 阶段（05–07）：框架期</strong> —— 引入 Python 三件套（LangChain/LangGraph/LangSmith），把前面的零件「组装」成可控的生产系统，并解决「多个 Agent 协同」和「状态不丢」的问题。</li><li data-src-line="93" data-src-file="ai/01-导论.md"><strong>第 3 阶段（08–11）：生产期</strong> —— 补上「记忆、观测、安全」这三块生产级 Agent 的必备能力，最后用一个端到端实战把它们串成一个能上线的整体。</li></ol><p data-src-line="95" data-src-file="ai/01-导论.md"><strong>特别提醒</strong>：记忆（08）、评估观测（09）、安全护栏（10）这三篇，很多人以为是「可选的加分项」，<strong>其实它们是生产级 Agent 的「必备件」，不是「可选件」</strong>——没有它们，你的 Agent 只能算「能跑的原型」，不能算「能上线的系统」。这套文档把它们单独成篇，正是为了纠正这个普遍误解。</p><hr><h2 id="_4-三个维度-贯穿全书" tabindex="-1" data-src-line="99" data-src-file="ai/01-导论.md">4. 三个维度，贯穿全书 <a class="header-anchor" href="#_4-三个维度-贯穿全书" aria-label="Permalink to &quot;4. 三个维度，贯穿全书&quot;">​</a></h2><p data-src-line="101" data-src-file="ai/01-导论.md">后面每一篇，都会围绕「<strong>安全、可靠、高效</strong>」这三个维度来回答「怎么用」。但有一点必须提前说透，否则你会读得很累：</p><p data-src-line="103" data-src-file="ai/01-导论.md"><strong>不同的组件，命门不同。</strong> 我们不会每篇都机械地三样全讲，而是「这个组件最怕出什么问题，就重点讲什么」。</p><ul data-src-line="105" data-src-file="ai/01-导论.md"><li data-src-line="105" data-src-file="ai/01-导论.md">有的组件，命门是<strong>高效</strong>（比如大模型调用，最怕烧钱、烧 Token）；</li><li data-src-line="106" data-src-file="ai/01-导论.md">有的组件，命门是<strong>可靠</strong>（比如记忆，最怕记错、串号、过时）；</li><li data-src-line="107" data-src-file="ai/01-导论.md">有的组件，命门是<strong>安全</strong>（比如让 Agent 调工具，最怕它越权、被注入攻击）。</li></ul><p data-src-line="109" data-src-file="ai/01-导论.md"><strong>带着这根弦去读，你会更快抓住每篇的重点</strong>——每读一篇，先问自己一个问题：「这一篇的命门是哪一维？」找到它，你就抓住了这篇的灵魂。</p><hr><h2 id="_5-新手最常犯的-3-个错" tabindex="-1" data-src-line="113" data-src-file="ai/01-导论.md">5. 新手最常犯的 3 个错 <a class="header-anchor" href="#_5-新手最常犯的-3-个错" aria-label="Permalink to &quot;5. 新手最常犯的 3 个错&quot;">​</a></h2><p data-src-line="115" data-src-file="ai/01-导论.md">这三个错，几乎每个学 Agent 的人都犯过。提前看清，能帮你省下几个月的弯路：</p><ol data-src-line="117" data-src-file="ai/01-导论.md"><li data-src-line="117" data-src-file="ai/01-导论.md"><p data-src-line="117" data-src-file="ai/01-导论.md"><strong>把「Agent」当成「更强的聊天机器人」</strong> —— 于是不配工具、不设循环，最后发现它「只会说不会做」。根因：没理解 Agent 的本质是「系统」而非「模型」。正确姿势：先接受「模型只是 Agent 的一个零件」，你要搭的是零件外面的那套系统。</p></li><li data-src-line="119" data-src-file="ai/01-导论.md"><p data-src-line="119" data-src-file="ai/01-导论.md"><strong>一上来就啃 API 文档</strong> —— 想学 Agent，直接去背框架的参数表、背 LangChain 的类名。根因：把「记 API」当成了「理解」。正确姿势：<strong>先建立心智模型（这套文档的每一篇都在做这件事），API 用到再查</strong>。心智模型是骨架，API 是皮肤；先有骨架，皮肤才有地方贴。</p></li><li data-src-line="121" data-src-file="ai/01-导论.md"><p data-src-line="121" data-src-file="ai/01-导论.md"><strong>跳过「安全」直接上线</strong> —— 觉得「护栏是以后的事」，结果 Agent 一上生产就干蠢事、闯大祸。根因：低估了「自主执行」的风险。正确姿势：从第 10 篇就明白，护栏不是「可选优化」，是「上线的底线」。</p></li></ol><hr><h2 id="_6-记住这一句" tabindex="-1" data-src-line="125" data-src-file="ai/01-导论.md">6. 记住这一句 <a class="header-anchor" href="#_6-记住这一句" aria-label="Permalink to &quot;6. 记住这一句&quot;">​</a></h2><blockquote data-src-line="127" data-src-file="ai/01-导论.md"><p data-src-line="127" data-src-file="ai/01-导论.md"><strong>Agent = 会聊天的模型 ＋ 干活的壳。你学的不是模型，更是那层壳怎么搭、怎么管、怎么不翻车。先建心智模型，再碰 API。</strong></p></blockquote><p data-src-line="129" data-src-file="ai/01-导论.md">从下一篇开始，我们走进这层壳的第一块砖：<strong>怎么让模型按你的要求好好说话</strong>（02 · LLM 接口与提示词工程）。</p>',53)])])}const h=t(e,[["render",s]]);export{f as __pageData,h as default};
